  story:[{h:"העולם שאחרי המלחמה",t:"בסוף שנות ה־40 העולם יצא ממלחמת העולם השנייה. מיליונים איבדו בני זוג, ומיליונים חיפשו להתחיל מחדש.<br><br>הפורמט שענה על הצורך היה <b>lonely hearts club</b> — מועדוני היכרות שפעלו דרך מודעות בעיתונים, וחיברו בין נשים בודדות לגברים בודדים.<br><br>עבור רוב האנשים זה היה בדיוק מה שזה נראה. עבור חלק מהנשים, זה היה משהו אחר."},{h:"ריימונד ומרתה",t:"<b>ריימונד פרננדז</b> פרסם מודעות והציג את עצמו כג׳נטלמן בעל אמצעים. הוא פנה לנשים בודדות, חיזר, ואז ניקז את חסכונותיהן.<br><br>ב־1947 אחת הנשים שענו למודעה שלו הייתה <b>מרתה בק</b>, אחות מוסמכת ואם לשניים מפלורידה. הוא ניסה להונות אותה כמו את השאר.<br><br>במקום זה, היא הצטרפה אליו."},{h:"\"אחותו\"",t:"מכאן ואילך השיטה השתנתה. בק נסעה עם פרננדז והוצגה בפני הנשים כ<b>אחותו</b>.<br><br>הנוכחות שלה עשתה את התרחיש אמין יותר — גבר שמגיע עם בת משפחה נראה פחות מאיים.<br><br>אבל היא גם הביאה איתה משהו אחר: <b>קנאה</b>. לפי עדויות מהמשפט, ההסלמה מהונאה לרצח קשורה ישירות לדינמיקה הזוגית ביניהם."},{h:"מהונאה לרצח",t:"ההונאות הפכו לרציחות. ההרשעה המרכזית התייחסה לרצח שבוצע בניו יורק, מה שאפשר להעמיד אותם לדין במדינה שבה עונש מוות היה בתוקף.<br><br>שאר המקרים — בפלורידה, במישיגן ובמדינות נוספות — נותרו ברמת חשד. <b>הערכות בזמן אמת דיברו על מספר דו־ספרתי.</b>"},{h:"סינג סינג",t:"המשפט ב־1949 היה אירוע תקשורתי. העיתונות התמקדה במראה של בק ובניסוחים משפילים כלפיה, בצורה שהיום נקראת אחרת לגמרי.<br><br>ב־<b>8 במרץ 1951</b> שניהם הוצאו להורג בכיסא החשמלי בכלא <b>סינג סינג</b>.<br><br>הסיפור עובד פעמיים לקולנוע: The Honeymoon Killers (1970) ו־Lonely Hearts (2006)."}],
  quotes:[{t:"הפרק הזה הוא סיפור על אהבה.",by:"מאיה גזית",role:"השורה שפותחת את הפוסט"},{t:"עבור חלק מהנשים שהיו במועדון הזה, המפגש עם גברים זרים הפך אותן לקורבנות.",by:"מאיה גזית",role:"מהפוסט"},{t:"זוג רוצחים שניהלו זוגיות רעילה וביחד רצחו נשים בודדות.",by:"מאיה גזית",role:"מהפוסט"},{t:"היא הוצגה בפני הנשים כאחותו.",by:"מתוך עדויות המשפט",role:"ניו יורק, 1949"},{t:"העיתונות התמקדה במראה שלה — בצורה שהיום נקראת אחרת לגמרי.",by:"הערת הארכיון",role:""}],
  victims:[{n:1,name:"נשות מועדוני הלבבות הבודדים",en:"Lonely Hearts Club victims", f:1, from:"ארצות הברית",date:"1947–1949",county:"מספר מדינות",act:"נשים בודדות שענו למודעות",d:"<b>הערת דיוק:</b> פרננדז ובק הורשעו בשלושה רציחות. הערכות חוקרים ותקשורת בזמן אמת דיברו על היקף גדול בהרבה — עד כ־20 — אך מקרים אלה לא הוכחו בבית משפט.<br><br>הקורבנות היו נשים בודדות, רבות מהן אלמנות מלחמה, שחיפשו קשר חדש דרך מודעות היכרות ונרצחו לאחר שכספן הועבר.",tags:["3 הרשעות","הערכות עד 20","לא כולן הוכחו"]}],
