  evidence:[{k:"ad",art:"letter",wide:true,t:"המודעה",s:"ראיה 01",p:"הכלי שאפשר הכל.",b:"מודעות \"לבבות בודדים\" בעיתונים היו הפורמט המקובל להיכרות בסוף שנות ה־40. אישה בודדה כתבה, גבר ענה, והתכתבות התחילה.<br><br>הפורמט הזה נתן לפרננדז שלושה דברים: <b>גישה</b> לנשים שחיו לבד, <b>לגיטימציה</b> לשאול על מצבן הכלכלי, ו<b>ניתוק</b> — הן לא הכירו איש שהכיר אותו.<br><br>ההקבלה לתיקים מודרניים בארכיון הזה — חליל, זליך — היא ישירה. הפלטפורמה משתנה, המנגנון לא."},
    {k:"sister",art:"users",t:"\"האחות\"",s:"ראיה 02",p:"למה זה עבד.",b:"הצעד שהפך את ההונאה לאפקטיבית במיוחד היה הצגתה של <b>מרתה בק כאחותו</b> של פרננדז.<br><br>גבר זר שמגיע לבית של אישה בודדה מעורר חשד. גבר שמגיע עם בת משפחה — לא.<br><br>בק גם ניהלה שיחות עם הנשים, יצרה אמון, ולעיתים לנה בבית."},
    {k:"jealousy",art:"mother",t:"הדינמיקה הזוגית",s:"ראיה 03",p:"ההסלמה מהונאה לרצח.",b:"לפי עדויות שהוצגו במשפט, המעבר מהונאה לרצח קשור לדינמיקה בין השניים.<br><br>בק הייתה נוכחת בזמן שפרננדז חיזר אחרי נשים אחרות כחלק מהתרמית — ולפי העדויות, לא הצליחה להפריד בין התפקיד למציאות.<br><br>מאיה תיארה את זה בפוסט כ<b>\"זוגיות רעילה\"</b>. זה גם מה שהתביעה טענה."},
    {k:"trial",art:"gavel",wide:true,t:"המשפט של 1949",s:"ראיה 04",p:"סיקור שנקרא היום אחרת.",b:"המשפט בניו יורק היה אירוע תקשורתי גדול. העיתונות סיקרה אותו בהרחבה — ובמידה רבה התמקדה ב<b>מראה החיצוני של מרתה בק</b>, במשקלה ובכינויים משפילים.<br><br><b>הערת הארכיון:</b> הסיקור הזה הוא חלק מהתיק ההיסטורי, לא הערת שוליים. הוא השפיע על האופן שבו הציבור תפס את שני הנאשמים — והוא נקרא היום אחרת לגמרי."},
    {k:"chair",art:"scale",t:"8 במרץ 1951",s:"ראיה 05",p:"סינג סינג.",b:"שניהם הוצאו להורג בכיסא החשמלי בכלא <b>סינג סינג</b> בניו יורק, ב־<b>8 במרץ 1951</b>.<br><br>העמדתם לדין דווקא בניו יורק לא הייתה מקרית: זו הייתה המדינה שבה ניתן היה להשית עונש מוות על התיק.<br><br>שאר המקרים החשודים — בפלורידה, במישיגן ובמדינות נוספות — לא הובאו לדין ולא הוכחו."}],
