  facts:[["נולד","23 באוגוסט 1943, סן אנטוניו, טקסס"],["1968","טלי שפירו, בת 8, נתקפה בלוס אנג׳לס. שרדה לאחר 32 יום בתרדמת"],["זהות בדויה","נמלט לניו יורק וחי בשמות John Berger ו־John Burger"],["השכלה","למד קולנוע ב־NYU תחת הזהות הבדויה"],["ספטמבר 1978","הופיע כרווק מס׳ 1 ב־The Dating Game וזכה. המתמודדת שריל ברדשו סירבה לצאת איתו"],["רובין סמסו","בת 12, נעלמה ב־20 ביוני 1979 בהאנטינגטון ביץ׳"],["קליפורניה","הורשע בחמישה רציחות במשפט השלישי, מרץ 2010"],["ניו יורק","הודה ב־2013 ברצח קורנליה קרילי ואלן הובר"],["וויומינג","הואשם ב־2016 ברצח כריסטין ת׳ורנטון. לא הועמד לדין בשל מצבו הרפואי"],["התצלומים","למעלה מ־1,000 תצלומים נתפסו במחסן שלו. 120 פורסמו ב־2010"],["מת","24 ביולי 2021, בכלא, מסיבות טבעיות"]],
  story:[{h:"1968",t:"ב־<b>25 בספטמבר 1968</b>, בהוליווד, אלקלה פיתה ילדה בת 8 בשם <b>טלי שפירו</b> לדירתו. עד ששוטר הגיע בעקבות דיווח של עד, היא הייתה במצב אנוש. היא הייתה <b>32 יום בתרדמת</b> — ושרדה.<br><br>אלקלה נמלט. הוא עבר לניו יורק וחי תחת השמות <b>John Berger</b> ו־<b>John Burger</b>.<br><br>הוא נרשם ללימודי קולנוע ב־NYU. משפחתה של שפירו עזבה את ארצות הברית, ובלי עדותה התיק נחלש."},{h:"הפער",t:"בשנים שלאחר מכן, אלקלה נעצר, שוחרר, ונעצר שוב על עבירות מין בקטינות. הוא ריצה תקופות מאסר קצרות ושוחרר.<br><br>במקביל — לפי מה שהוכח מאוחר יותר — הוא רצח נשים בשתי חופי היבשת. <b>קורנליה קרילי</b> (1971) ו<b>אלן הובר</b> (1977) בניו יורק; <b>ג׳יל ברקומב</b>, <b>ג׳ורג׳יה וויקסטד</b>, <b>שרלוט לאם</b> ו<b>ג׳יל פרנטו</b> בקליפורניה.<br><br>אף אחת מהרשויות לא קישרה ביניהם."},{h:"ספטמבר 1978",t:"ב־<b>ספטמבר 1978</b> אלקלה הופיע בתוכנית <b>The Dating Game</b> כרווק מספר 1. הוא הוצג כצלם. הוא ניצח.<br><br><b>שריל ברדשו</b>, המתמודדת, סירבה בסופו של דבר לצאת איתו. היא אמרה בדיעבד שהוא נראה לה <em>מצמרר</em>.<br><br>באותה תקופה הוא היה רוצח פעיל, עם הרשעות קודמות בעבירות מין בקטינות. <b>אף בדיקת רקע לא עצרה אותו מלהגיע לאולפן.</b>"},{h:"רובין",t:"ב־<b>20 ביוני 1979</b> נעלמה <b>רובין סמסו</b>, בת 12, בדרכה לשיעור בלט בהאנטינגטון ביץ׳.<br><br>עדה תיארה גבר שצילם אותה ואת חברתה על החוף. מהתיאור הופק קלסתרון. פקח מבחן זיהה בו את אלקלה.<br><br>במחסן שכור שלו בסיאטל נמצאו עגילים של רובין — ו<b>למעלה מ־1,000 תצלומים</b> של נשים וילדות."},{h:"41 שנה",t:"ההרשעה הראשונה ברצח סמסו ניתנה ב־1980 ובוטלה ב־1984. ההרשעה השנייה ניתנה ב־1986 ובוטלה ב־2003.<br><br>רק ב<b>משפט השלישי, במרץ 2010</b>, הוא הורשע בחמישה רציחות בקליפורניה. ב־2013 הוא הודה בשתי רציחות נוספות בניו יורק.<br><br>הוא מת ב־24 ביולי 2021, בן 77. <b>מספר הקורבנות האמיתי אינו ידוע.</b>"}],
  quotes:[{t:"בספטמבר 1978 שודר בארצות הברית פרק בתוכנית ריאליטי פופולרית ששנים אחר כך קיבל משמעות חדשה לגמרי.",by:"מאיה גזית",role:"מהפוסט על הפרק"},{t:"הוא נראה לי מצמרר.",by:"שריל ברדשו",role:"המתמודדת שסירבה לצאת איתו"},{t:"טלי שפירו הייתה 32 יום בתרדמת — ושרדה.",by:"מתוך תיעוד המקרה",role:"ספטמבר 1968"},{t:"למעלה מ־1,000 תצלומים נמצאו במחסן שכור. רובם לא זוהו עד היום.",by:"ממצאי החקירה",role:"1979"},{t:"שלושה משפטים ו־41 שנה עברו עד שהרשעה עמדה.",by:"הערת הארכיון",role:""}],
